1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Todos</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    padding: 2rem 1rem;
12	    font: 16px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
13	    background: #f5f5f4;
14	    color: #1c1917;
15	  }
16	  main { max-width: 32rem; margin: 0 auto; }
17	  h1 { margin: 0 0 1rem; font-size: 1.5rem; }
18	  form { display: flex; gap: 0.5rem; }
19	  input[type="text"], input[type="search"] {
20	    flex: 1;
21	    min-width: 0;
22	    padding: 0.6rem 0.75rem;
23	    font: inherit;
24	    border: 1px solid #d6d3d1;
25	    border-radius: 6px;
26	    background: #fff;
27	  }
28	  button {
29	    padding: 0.6rem 1rem;
30	    font: inherit;
31	    border: 0;
32	    border-radius: 6px;
33	    background: #1c1917;
34	    color: #fff;
35	    cursor: pointer;
36	  }
37	  ul { list-style: none; margin: 1rem 0 0; padding: 0; }
38	  li {
39	    display: flex;
40	    align-items: center;
41	    gap: 0.5rem;
42	    padding: 0.6rem 0.75rem;
43	    margin-bottom: 0.5rem;
44	    background: #fff;
45	    border: 1px solid #e7e5e4;
46	    border-radius: 6px;
47	  }
48	  li span { flex: 1; overflow-wrap: anywhere; }
49	  li button { background: transparent; color: #b91c1c; padding: 0.25rem 0.5rem; }
50	  li button:hover { background: #fee2e2; }
51	  li input[type="checkbox"] { width: 1.1rem; height: 1.1rem; margin: 0; cursor: pointer; }
52	  li[data-completed="true"] span { color: #a8a29e; text-decoration: line-through; }
53	  input[type="date"], select {
54	    padding: 0.5rem;
55	    font: inherit;
56	    border: 1px solid #d6d3d1;
57	    border-radius: 6px;
58	    background: #fff;
59	  }
60	  li .due { flex: none; font-size: 0.85rem; color: #57534e; }
61	  li[data-overdue="true"] { border-color: #fca5a5; background: #fef2f2; }
62	  li[data-overdue="true"] .due { color: #b91c1c; font-weight: 600; }
63	  /* [REQ-006] Priority shown as plain text, no colour, so only overdue is highlighted. */
64	  li .priority { flex: none; font-size: 0.85rem; color: #57534e; }
65	  /* [REQ-007] */
66	  .search { display: block; width: 100%; margin-top: 1rem; }
67	  li input.edit { padding: 0.25rem 0.5rem; }
68	  .filters { display: flex; gap: 0.5rem; margin-top: 1rem; }
69	  .filters button { background: transparent; color: #1c1917; border: 1px solid #d6d3d1; padding: 0.35rem 0.75rem; }
70	  .filters button[aria-pressed="true"] { background: #1c1917; color: #fff; border-color: #1c1917; }
71	</style>
72	</head>
73	<body>
74	<main>
75	  <h1>Todos</h1>
76	  <form id="todo-form">
77	    <input type="text" data-testid="todo-input" placeholder="What needs doing?" autocomplete="off" aria-label="New todo">
78	    <input type="date" data-testid="todo-due" aria-label="Due date (optional)">
79	    <select data-testid="todo-priority" aria-label="Priority">
80	      <option value="low">Low</option>
81	      <option value="med" selected>Med</option>
82	      <option value="high">High</option>
83	    </select>
84	    <button type="submit" data-testid="todo-add">Add</button>
85	  </form>
86	  <input type="search" class="search" data-testid="search-input" placeholder="Search todos" autocomplete="off" aria-label="Search todos">
87	  <div class="filters" role="group" aria-label="Filter todos">
88	    <button type="button" data-testid="filter-all" data-filter="all" aria-pressed="true">All</button>
89	    <button type="button" data-testid="filter-active" data-filter="active" aria-pressed="false">Active</button>
90	    <button type="button" data-testid="filter-completed" data-filter="completed" aria-pressed="false">Completed</button>
91	  </div>
92	  <ul data-testid="todo-list"></ul>
93	</main>
94	<script>
95	(function () {
96	  var STORAGE_KEY = 'todos';
97	  var form = document.getElementById('todo-form');
98	  var input = document.querySelector('[data-testid="todo-input"]');
99	  var list = document.querySelector('[data-testid="todo-list"]');
100	  var dueInput = document.querySelector('[data-testid="todo-due"]');
101	  var priorityInput = document.querySelector('[data-testid="todo-priority"]');
102	  var searchInput = document.querySelector('[data-testid="search-input"]');
103	
104	  // [REQ-001]
105	  function makeId() {
106	    if (window.crypto && typeof window.crypto.randomUUID === 'function') {
107	      return window.crypto.randomUUID();
108	    }
109	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
110	  }
111	
112	  // [REQ-001]
113	  function loadTodos() {
114	    try {
115	      var parsed = JSON.parse(localStorage.getItem(STORAGE_KEY));
116	      return Array.isArray(parsed) ? parsed : [];
117	    } catch (e) {
118	      return [];
119	    }
120	  }
121	
122	  // [REQ-001]
123	  function saveTodos() {
124	    try {
125	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
126	    } catch (e) {}
127	  }
128	
129	  var todos = loadTodos();
130	  var filter = 'all';
131	  var filterButtons = document.querySelectorAll('[data-filter]');
132	  var search = '';        // [REQ-007]
133	  var editingId = null;   // [REQ-007] id of the todo whose text is being edited
134	  var editDraft = '';
135	  var rendering = false;  // [REQ-007] ignore blur caused by render removing the field
136	
137	  // [REQ-002] Active todos first, then completed.
138	  // [REQ-005] Within each group: high, then med, then low; same priority keeps insertion order.
139	  function orderedTodos() {
140	    var result = [];
141	    [false, true].forEach(function (completed) {
142	      ['high', 'med', 'low'].forEach(function (p) {
143	        todos.forEach(function (t) {
144	          if (!!t.completed === completed && normalizePriority(t.priority) === p) result.push(t);
145	        });
146	      });
147	    });
148	    return result;
149	  }
150	
151	  // [REQ-003] Today's LOCAL calendar date as YYYY-MM-DD (never via UTC).
152	  function todayLocal() {
153	    var d = new Date();
154	    var m = d.getMonth() + 1;
155	    var day = d.getDate();
156	    return d.getFullYear() + '-' + (m < 10 ? '0' : '') + m + '-' + (day < 10 ? '0' : '') + day;
157	  }
158	
159	  // [REQ-003] Accept only a plain YYYY-MM-DD string; anything else means no due date.
160	  function normalizeDue(value) {
161	    return typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) ? value : '';
162	  }
163	
164	  // [REQ-003] Overdue = due date strictly before today's local date. Date-only string compare.
165	  function isOverdue(todo, today) {
166	    var due = normalizeDue(todo.due);
167	    return due !== '' && due < today;
168	  }
169	
170	  // [REQ-004] Only low, med or high; anything else (including older todos) is med.
171	  function normalizePriority(value) {
172	    return value === 'low' || value === 'high' ? value : 'med';
173	  }
174	
175	  // [REQ-002]
176	  function isVisible(todo) {
177	    if (filter === 'active') return !todo.completed;
178	    if (filter === 'completed') return !!todo.completed;
179	    return true;
180	  }
181	
182	  // [REQ-007] Case-insensitive substring match; combines with the filter in render.
183	  function matchesSearch(todo) {
184	    return String(todo.text).toLowerCase().indexOf(search.toLowerCase()) !== -1;
185	  }
186	
187	  // [REQ-001]
188	  function render() {
189	    rendering = true;
190	    try { renderList(); } finally { rendering = false; }
191	  }
192	
193	  function renderList() {
194	    list.textContent = '';
195	    filterButtons.forEach(function (btn) {
196	      btn.setAttribute('aria-pressed', String(btn.getAttribute('data-filter') === filter));
197	    });
198	    var today = todayLocal();
199	    orderedTodos().filter(function (t) { return isVisible(t) && matchesSearch(t); }).forEach(function (todo) {
200	      var li = document.createElement('li');
201	      li.setAttribute('data-testid', 'todo-item');
202	      li.setAttribute('data-id', todo.id);
203	      li.setAttribute('data-completed', String(!!todo.completed));
204	      li.setAttribute('data-overdue', String(isOverdue(todo, today)));
205	      li.setAttribute('data-priority', normalizePriority(todo.priority)); // [REQ-004]
206	
207	      var toggle = document.createElement('input');
208	      toggle.type = 'checkbox';
209	      toggle.setAttribute('data-testid', 'todo-toggle');
210	      toggle.setAttribute('aria-label', 'Mark complete');
211	      toggle.checked = !!todo.completed;
212	      toggle.addEventListener('change', function () { toggleTodo(todo.id); });
213	      li.appendChild(toggle);
214	
215	      var text;
216	      if (todo.id === editingId) {
217	        // [REQ-007] Enter or blur commits, Escape cancels.
218	        text = document.createElement('input');
219	        text.type = 'text';
220	        text.className = 'edit';
221	        text.setAttribute('data-testid', 'todo-edit-input');
222	        text.setAttribute('aria-label', 'Edit todo');
223	        text.value = editDraft;
224	        text.addEventListener('input', function () { editDraft = text.value; });
225	        text.addEventListener('keydown', function (e) {
226	          if (e.key === 'Enter') { e.preventDefault(); commitEdit(); }
227	          else if (e.key === 'Escape') { e.preventDefault(); cancelEdit(); }
228	        });
229	        text.addEventListener('blur', function () { if (!rendering) commitEdit(); });
230	      } else {
231	        text = document.createElement('span');
232	        text.setAttribute('data-testid', 'todo-text');
233	        text.textContent = todo.text;
234	        text.addEventListener('dblclick', function () { startEdit(todo.id); }); // [REQ-007]
235	      }
236	
237	      var del = document.createElement('button');
238	      del.type = 'button';
239	      del.setAttribute('data-testid', 'todo-delete');
240	      del.setAttribute('aria-label', 'Delete todo');
241	      del.textContent = 'Delete';
242	      del.addEventListener('click', function () { deleteTodo(todo.id); });
243	
244	      li.appendChild(text);
245	
246	      // [REQ-006] Priority as an uncoloured text label.
247	      var priorityEl = document.createElement('span');
248	      priorityEl.className = 'priority';
249	      priorityEl.textContent = { low: 'Low', med: 'Med', high: 'High' }[normalizePriority(todo.priority)];
250	      li.appendChild(priorityEl);
251	
252	      // [REQ-003] Show the stored string as-is so no timezone shift can occur.
253	      var due = normalizeDue(todo.due);
254	      if (due) {
255	        var dueEl = document.createElement('span');
256	        dueEl.className = 'due';
257	        dueEl.setAttribute('data-testid', 'todo-due-date');
258	        dueEl.textContent = 'Due ' + due;
259	        li.appendChild(dueEl);
260	      }
261	
262	      li.appendChild(del);
263	      list.appendChild(li);
264	    });
265	  }
266	
267	  // [REQ-001]
268	  function addTodo(text, due, priority) {
269	    text = text.trim();
270	    if (!text) return;
271	    // [REQ-003] due is optional, stored as a YYYY-MM-DD string or ''.
272	    todos.push({ id: makeId(), text: text, createdAt: Date.now(), completed: false, due: normalizeDue(due), priority: normalizePriority(priority) }); // [REQ-004]
273	    saveTodos();
274	    render();
275	  }
276	
277	  // [REQ-002]
278	  function toggleTodo(id) {
279	    todos.forEach(function (t) {
280	      if (t.id === id) t.completed = !t.completed;
281	    });
282	    saveTodos();
283	    render();
284	  }
285	
286	  // [REQ-007]
287	  function startEdit(id) {
288	    todos.forEach(function (t) {
289	      if (t.id === id) { editingId = id; editDraft = t.text; }
290	    });
291	    render();
292	    var field = list.querySelector('[data-testid="todo-edit-input"]');
293	    if (field) {
294	      field.focus();
295	      field.setSelectionRange(field.value.length, field.value.length);
296	    }
297	  }
298	
299	  // [REQ-007] Blank text keeps the old text instead of deleting the todo.
300	  function commitEdit() {
301	    if (editingId === null) return;
302	    var id = editingId;
303	    var value = editDraft.trim();
304	    editingId = null;
305	    if (value) {
306	      todos.forEach(function (t) { if (t.id === id) t.text = value; });
307	      saveTodos();
308	    }
309	    render();
310	  }
311	
312	  // [REQ-007]
313	  function cancelEdit() {
314	    editingId = null;
315	    render();
316	  }
317	
318	  // [REQ-002]
319	  function setFilter(value) {
320	    filter = value;
321	    render();
322	  }
323	
324	  filterButtons.forEach(function (btn) {
325	    btn.addEventListener('click', function () { setFilter(btn.getAttribute('data-filter')); });
326	  });
327	
328	  // [REQ-007]
329	  searchInput.addEventListener('input', function () {
330	    search = searchInput.value;
331	    render();
332	  });
333	
334	  // [REQ-001]
335	  function deleteTodo(id) {
336	    todos = todos.filter(function (t) { return t.id !== id; });
337	    saveTodos();
338	    render();
339	  }
340	
341	  form.addEventListener('submit', function (e) {
342	    e.preventDefault();
343	    addTodo(input.value, dueInput.value, priorityInput.value);
344	    input.value = '';
345	    dueInput.value = '';
346	    priorityInput.value = 'med';
347	    input.focus();
348	  });
349	
350	  // [REQ-003] Refresh overdue state when the page returns after the date may have changed.
351	  document.addEventListener('visibilitychange', function () {
352	    if (!document.hidden) render();
353	  });
354	
355	  render();
356	})();
357	</script>
358	</body>
359	</html>
