p='index.html'; s=open(p).read()
def rep(a,b):
    global s
    assert s.count(a)==1, a
    s=s.replace(a,b)
rep('''  .filters button[aria-pressed="true"] { background: #1c1917; color: #fff; border-color: #1c1917; }
''','''  .filters button[aria-pressed="true"] { background: #1c1917; color: #fff; border-color: #1c1917; }
  /* [REQ-009] */
  .bulk { display: flex; gap: 0.5rem; margin-top: 0.5rem; }
  .bulk button { background: transparent; color: #1c1917; border: 1px solid #d6d3d1; padding: 0.35rem 0.75rem; }
''')
rep('''  </div>
  <ul data-testid="todo-list"></ul>''','''  </div>
  <div class="bulk" role="group" aria-label="Bulk actions">
    <button type="button" data-testid="bulk-mark-all">Mark all complete</button>
    <button type="button" data-testid="bulk-clear-completed">Clear completed</button>
  </div>
  <ul data-testid="todo-list"></ul>''')
rep('''  form.addEventListener('submit',''','''  // [REQ-009] Mutates in place; orderedTodos re-derives grouping and priority order, and the array keeps insertion order.
  function markAllComplete() {
    todos.forEach(function (t) { t.completed = true; });
    saveTodos();
    render();
  }

  // [REQ-009]
  function clearCompleted() {
    todos = todos.filter(function (t) { return !t.completed; });
    saveTodos();
    render();
  }

  document.querySelector('[data-testid="bulk-mark-all"]').addEventListener('click', markAllComplete);
  document.querySelector('[data-testid="bulk-clear-completed"]').addEventListener('click', clearCompleted);

  form.addEventListener('submit',''')
open(p,'w').write(s)
EOF
